using namespace std;
#define FOR(i,a,b) for(int i=(int)(a); i < (int)(b); ++i )
#define rep(i,n) FOR(i,0,n)
using ll = long long;
const ll MOD=1000000007LL;
const ll INF=1LL<<60;

template<typename T>
struct Matrix{
    int rows,cols;
    vector<T> data;
    Matrix(int s=0):rows(s),cols(s),data(s*s,0){}
    Matrix(int h,int w):rows(h),cols(w),data(h*w,0){}
    T& at(int r,int c){return data[r*cols+c];}
    T at(int r,int c)const{return data[r*cols+c];}
    Matrix& operator+=(const Matrix& m){
        assert(rows==m.rows && cols==m.cols);
        for(int i=0;i<rows*cols;++i) data[i]+=m.data[i];
        return *this;
    }
    Matrix& operator-=(const Matrix& m){
        assert(rows==m.rows && cols==m.cols);
        for(int i=0;i<rows*cols;++i) data[i]=(data[i]-m.data[i]+MOD)%MOD;
        return *this;
    }
    Matrix& operator*=(const Matrix& m){
        assert(cols==m.rows);
        Matrix res(rows,m.cols);
        for(int i=0;i<rows;++i){
            for(int j=0;j<m.cols;++j){
                for(int k=0;k<cols;++k){
                    res.at(i,j)=(res.at(i,j)+at(i,k)*m.at(k,j))%MOD;
                }
            }
        }
        return (*this)=res;
    }
    Matrix operator+(const Matrix& m)const{return Matrix(*this)+=m;}
    Matrix operator-(const Matrix& m)const{return Matrix(*this)-=m;}
    Matrix operator*(const Matrix& m)const{return Matrix(*this)*=m;}
};

template<typename T>
Matrix<T> identity(int n){
    Matrix<T> I(n);
    for(int i=0;i<n;++i) I.at(i,i)=1;
    return I;
}

template<typename T>
Matrix<T> fast_pow(Matrix<T> base,int exp){
    assert(base.rows==base.cols);
    Matrix<T> result=identity<T>(base.rows);
    while(exp>0){
        if(exp&1) result*=base;
        base*=base;
        exp>>=1;
    }
    return result;
}

Matrix<ll> base_matrix[65];

Matrix<ll> compute_trans(int i,int k){
    return fast_pow(base_matrix[i+k],k-i)*fast_pow(base_matrix[i],i);
}

ll compute(ll n,ll k){
    if(n==0) return 1;
    int digits=0;
    ll t=n;
    while(t>0){
        ++digits;
        t/=k;
    }
    Matrix<ll> trans[digits+5],pow_trans[digits+5];
    trans[0]=base_matrix[k-1];
    pow_trans[0]=fast_pow(trans[0],k-1);
    if(digits>1){
        trans[1]=compute_trans(k-1,k);
        pow_trans[1]=fast_pow(trans[1],k-1);
    }
    Matrix<ll> suffix_prod=identity<ll>(2*k+1);
    FOR(j,2,digits+1){
        trans[j]=compute_trans(k-j%k,k);
        suffix_prod*=pow_trans[j-1];
        trans[j]*=suffix_prod;
        pow_trans[j]=fast_pow(trans[j],k-1);
    }
    int pos_idx=1;
    int remainder=n%k;
    n-=remainder;
    int shift=0;
    t=n;
    if(t>0){
        while(t%k==0){
            ++shift;
            t/=k;
        }
    }
    shift=(k-shift%k)%k;
    Matrix<ll> result=identity<ll>(2*k+1);
    result=fast_pow(base_matrix[shift],remainder)*fast_pow(base_matrix[shift+k],max(remainder-shift,0LL));
    n/=k;
    if(n==0){
        return (result.at(2*k,0)+result.at(0,0))%MOD;
    }
    --n;
    while(n>0){
        ll digit=n%k;
        if(digit>0){
            result*=fast_pow(trans[pos_idx],digit);
        }
        n/=k;
        ++pos_idx;
    }
    result*=trans[1];
    return (result.at(2*k,0)+result.at(0,0))%MOD;
}

int main(){
    ll n,k;
    cin>>n>>k;
    rep(i,2*k+1){
        base_matrix[i]=Matrix<ll>(2*k+1);
        rep(j,i) base_matrix[i].at(0,j)=1;
        rep(j,2*k-1) base_matrix[i].at(j+1,j)=1;
        base_matrix[i].at(2*k,0)=1;
        base_matrix[i].at(2*k,2*k)=1;
    }
    cout<<compute(n,k)<<endl;
    return 0;
}
